#!/usr/bin/env bash
#
# keyboard-settings.sh - Keyboard layout menu for Kayra OS.
#
# Opens a fuzzel menu with the keyboard layouts and variants that are
# generated by generate-keyboard-data.sh. The layout that is active in the
# sway configuration is marked with a check icon. The selected layout is
# applied with set-keyboard-layout.sh.
#
# Used commands: fuzzel, pkill, awk, sed, printf
# Used libraries: i18n.sh, klog.sh, notify.sh, single-instance.sh

export LC_ALL=C.UTF-8

set -uo pipefail

source "$(dirname "$0")/i18n.sh"
declare -n MSG=i18n_KEYBOARD_SETTINGS

source "$(dirname "$0")/klog.sh"
source "$(dirname "$0")/notify.sh"
source "$(dirname "$0")/single-instance.sh"

single_instance "keyboard-settings"

DATA_DIR="$HOME/.local/bin/data"
DATA_FILE="$DATA_DIR/keyboard-data"
MENU_FILE="$DATA_DIR/fuzzel-keyboard-menu"
CONFIG_FILE="$HOME/.config/sway/input-keyboard.conf"

# Material symbols that are used in the menu.
ICON_CHECK=$(printf '%b' '\U000E5E0')
ICON_KEYBOARD=$(printf '%b' '\U000E30C')

# The icon of the notifications.
NOTIFY_ICON="$ICON_KEYBOARD"

# The data files are generated by generate-keyboard-data.sh.
if [[ ! -f "$DATA_FILE" || ! -f "$MENU_FILE" ]]; then
    log ERROR "Keyboard data files are missing in $DATA_DIR"
    notify_error "${MSG[NOTIFY_TITLE]}" "${MSG[ERROR_DATA_NOT_FOUND]}"
    exit 1
fi

# Read the active layout and variant from the sway configuration.
CURRENT_LAYOUT=""
CURRENT_VARIANT=""

if [[ -f "$CONFIG_FILE" ]]; then
    CURRENT_LAYOUT=$(sed -n 's/.*xkb_layout[[:space:]]*"\([^"]*\)".*/\1/p' "$CONFIG_FILE" | head -1)
    CURRENT_VARIANT=$(sed -n 's/.*xkb_variant[[:space:]]*"\([^"]*\)".*/\1/p' "$CONFIG_FILE" | head -1)
fi

# Print the display name of the given layout and variant.
lookup_name() {
    awk -F'|' -v want_layout="$1" -v want_variant="$2" '
        {
            name = $1
            sub(/^[[:space:]]+/, "", name)
            sub(/[[:space:]]+$/, "", name)
            if ($2 == want_layout && $3 == want_variant) {
                print name
                exit
            }
        }
    ' "$DATA_FILE"
}

CURRENT_NAME=""
if [[ -n "$CURRENT_LAYOUT" ]]; then
    CURRENT_NAME=$(lookup_name "$CURRENT_LAYOUT" "$CURRENT_VARIANT")
    [[ -n "$CURRENT_NAME" ]] || CURRENT_NAME="$CURRENT_LAYOUT"
fi

# Build the menu entries. The active layout is marked with the check icon.
declare -a MENU_LINES=()

mapfile -t MENU_LINES < <(
    awk -F'|' -v icon="$ICON_CHECK" \
        -v cur_layout="$CURRENT_LAYOUT" -v cur_variant="$CURRENT_VARIANT" '
        {
            name = $1
            sub(/^[[:space:]]+/, "", name)
            sub(/[[:space:]]+$/, "", name)
            if (name == "") next
            if ($2 == cur_layout && $3 == cur_variant) {
                printf "%s %s\n", icon, name
                next
            }
            printf "%s\n", name
        }
    ' "$DATA_FILE"
)

if [[ ${#MENU_LINES[@]} -eq 0 ]]; then
    log ERROR "The keyboard data file has no entries: $DATA_FILE"
    notify_error "${MSG[NOTIFY_TITLE]}" "${MSG[ERROR_DATA_NOT_FOUND]}"
    exit 1
fi

# Window width of the longest menu entry (icon counted as 3 characters).
MAX_WIDTH=$(printf '%s\n' "${MENU_LINES[@]}" | awk '{ n = length($0) - 1 + 3; if (n > m) m = n } END { print m+0 }')

# Close any existing fuzzel process before opening the menu.
pkill -x fuzzel 2>/dev/null || true

SELECTED=$(printf '%s\n' "${MENU_LINES[@]}" | \
    fuzzel --dmenu --log-no-syslog --minimal-lines --lines="${#MENU_LINES[@]}" --width="$MAX_WIDTH" --prompt="${MSG[PROMPT_SELECT]}" "$@") || true

# Exit if the user cancelled the menu.
[[ -z "$SELECTED" ]] && exit 0

# Remove the check icon from the selected entry.
if [[ "$SELECTED" == "$ICON_CHECK "* ]]; then
    SELECTED_NAME="${SELECTED#"$ICON_CHECK "}"
else
    SELECTED_NAME="$SELECTED"
fi

[[ -z "$SELECTED_NAME" ]] && exit 0

# The selection is the layout that is already active.
if [[ -n "$CURRENT_NAME" && "$SELECTED_NAME" == "$CURRENT_NAME" ]]; then
    log INFO "The keyboard layout is already set: $SELECTED_NAME"
    notify_info "${MSG[NOTIFY_TITLE]}" "${MSG[MSG_UNCHANGED]}"
    exit 0
fi

# Apply the selected layout.
RESULT=$("$HOME/.local/bin/set-keyboard-layout.sh" "$SELECTED_NAME" 2>&1)
STATUS=$?

if [[ $STATUS -eq 0 ]]; then
    log INFO "Keyboard layout changed to: $SELECTED_NAME"
    notify_ok "${MSG[NOTIFY_TITLE]}" "$(i18n_template "${MSG[MSG_CHANGED]}" "LAYOUT=$SELECTED_NAME")"
else
    log ERROR "Failed to change the keyboard layout to $SELECTED_NAME: $RESULT"
    notify_error "${MSG[NOTIFY_TITLE]}" "${MSG[MSG_FAILED]}"
    exit 1
fi
